.ds-button {font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif; font-size: 13px; color: var(--text, #1d1d1f);cursor: default;}
.ds-button {
  height: 32px;
  padding: 0 12px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border-radius: 8px;
  border: 1px solid var(--line, #e6e6ea);
  background: var(--card, #fff);
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
}
.ds-button:hover:not(:disabled) {
  background: #f4f4f6;
}
.ds-button:focus-visible {outline: 2px solid #3478f6; outline-offset: 2px;}
.ds-button:disabled {opacity: 0.5;}

