.ds-nav-item {font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif; font-size: 13px; color: var(--text, #1d1d1f);cursor: default;}
.ds-nav-item {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  height: 32px;
  padding: 0 10px;
  margin: 1px 0;
  border: 1px solid transparent;
  border-radius: 8px;
  background: none;
  text-align: left;
  font-size: 13.5px;
  color: #333336;
}
.ds-nav-item:hover {
  background: var(--hover, #ebebee);
}
.ds-nav-item.ds-active {
  background: var(--card, #fff);
  border-color: var(--line, #e6e6ea);
  box-shadow: 0 1px 2px #0000000a;
  font-weight: 550;
}
.ds-nav-item:focus-visible {outline: 2px solid #3478f6; outline-offset: 2px;}

.ds-tag {font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif; font-size: 13px; color: var(--text, #1d1d1f);}
.ds-tag {
  font-size: 11px;
  font-weight: 500;
  color: var(--text-2, #6e6e73);
  background: #f2f2f4;
  border-radius: 5px;
  padding: 1px 6px;
}

.ds-chip {font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif; font-size: 13px; color: var(--text, #1d1d1f);}
.ds-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  max-width: 260px;
  padding: 3px 8px;
  border-radius: 6px;
  background: #f4f4f6;
  border: 1px solid var(--line-soft, #efeff2);
  font-size: 11.5px;
  font-family: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ds-card, .ds-row {font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif; font-size: 13px; color: var(--text, #1d1d1f);}
.ds-card {
  background: var(--card, #fff);
  border: 1px solid var(--line, #e6e6ea);
  border-radius: var(--radius, 12px);
}
.ds-list {
  overflow: hidden;
}
.ds-row {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  min-height: 56px;
  padding: 10px 16px;
  border: 0;
  border-top: 1px solid var(--line-soft, #efeff2);
  background: none;
  text-align: left;
}
.ds-list-head + .ds-row,
.ds-row:first-child {
  border-top: 0;
}
.ds-row.ds-clickable:hover {
  background: #fafafb;
}
.ds-row-main {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.ds-row-title {
  font-size: 14px;
  font-weight: 550;
  display: flex;
  align-items: center;
  gap: 8px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ds-row-meta {
  font-size: 12px;
  color: var(--text-2, #6e6e73);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ds-row:focus-visible {outline: 2px solid #3478f6; outline-offset: 2px;}

.ds-status {font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif; font-size: 13px; color: var(--text, #1d1d1f);}
.ds-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  display: inline-block;
  flex-shrink: 0;
  background: var(--text-3, #a1a1a6);
}
.ds-dot-ok {
  background: var(--ok, #1f9d55);
}
.ds-status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--text-2, #6e6e73);
  font-size: 12px;
  white-space: nowrap;
}
